package server

import (
	"reflect"
	"strings"
	"time"

	"github.com/mark3labs/mcp-go/v2/mcp"

	"github.com/slopster67/mcpproxy-go/internal/config"
)

// The input schema of the `profiles` admin tool. The profile
// properties are generated by reflection from config.ProfileConfig's JSON tags,
// so the tool cannot drift from the REST body: a field added to ProfileConfig
// appears on MCP with the same name and type, and a test pins the property set.

// profilesOperations is the `operation` enum, in documentation order.
var profilesOperations = []string{
	"list", "get", "create", "update", "delete", "rename", "assign",
	"list_clients", "effective_tools", "explain",
}

// profilesOpArgs are the arguments beyond the ProfileConfig fields (REST field
// and query names). Their descriptions are one line each: the schema is listed
// for every administrator session, so its size is tool-surface cost (H13).
var profilesOpArgs = []struct {
	name string
	desc string
	enum []string
	typ  string
}{
	{name: "new_name", typ: "string", desc: "rename: the new profile name."},
	{name: "reassign_to", typ: "string", desc: "delete: another existing profile that takes over the clients."},
	{name: "force", typ: "boolean", desc: "delete: delete although in use, leaving pins dangling."},
	{name: "tool", typ: "string", desc: "explain: upstream tool as server:tool."},
	{name: "client", typ: "string", desc: "assign, explain, effective_tools, list_clients: client id."},
	{name: "profile", typ: "string", desc: "assign: profile to bind (\"\" = All servers). explain, list_clients: profile ID (list_clients \"-\" = All servers)."},
	{name: "mode", typ: "string", enum: []string{"locked", "switchable"}, desc: "assign: binding mode; omitted keeps the current mode (profile \"\" is switchable)."},
	{name: "from_profile", typ: "string", desc: "assign (bulk): move every client bound to this profile (\"\" = All servers)."},
	{name: "to_profile", typ: "string", desc: "assign (bulk): the profile they move to (\"\" = All servers)."},
	{name: "server", typ: "string", desc: "effective_tools: keep only this server's rows."},
	{name: "reason", typ: "string", desc: "effective_tools: keep only rows with this access reason."},
}

// profileConfigDescriptions are the one-line descriptions of the ProfileConfig
// properties. A field without an entry still appears, with a generic line.
var profileConfigDescriptions = map[string]string{
	"id":             "get, update, delete, rename, effective_tools: the stable profile ID returned by list or create. Omit on create.",
	"name":           "create, update: the human-readable profile name.",
	"selected_tools": "create, update: exact tool-name arrays per server; a missing server key includes all tools from that server.",
	"servers":        "create, update: servers the profile reaches (no tools when empty).",
	"switchable_to":  "create, update: profile IDs a session may set_profile into; [] = none, omitted = unset.",
}

// profileConfigSchemaOverrides pin the enumerations the Go types cannot carry.

// profileConfigJSONFields lists the JSON property names of config.ProfileConfig
// in declaration order (the source of truth for the tool's profile properties).
func profileConfigJSONFields() []string {
	t := reflect.TypeOf(config.ProfileConfig{})
	out := make([]string, 0, t.NumField())
	for i := 0; i < t.NumField(); i++ {
		if name := jsonFieldName(t.Field(i)); name != "" {
			out = append(out, name)
		}
	}
	return out
}

func jsonFieldName(f reflect.StructField) string {
	tag := f.Tag.Get("json")
	if tag == "-" || !f.IsExported() {
		return ""
	}
	name, _, _ := strings.Cut(tag, ",")
	if name == "" {
		return f.Name
	}
	return name
}

// jsonSchemaForType renders the JSON schema of a Go type the way encoding/json
// sees it: pointers are transparent, a slice is an array, a map with string
// values is an object, a struct is an object of its JSON-tagged fields.
func jsonSchemaForType(t reflect.Type) map[string]any {
	for t.Kind() == reflect.Pointer {
		t = t.Elem()
	}
	if t == reflect.TypeOf(config.OAuthPatch{}) {
		schema := jsonSchemaForType(reflect.TypeOf(config.OAuthConfig{}))
		for name, property := range schema["properties"].(map[string]any) {
			schema["properties"].(map[string]any)[name] = map[string]any{"anyOf": []any{property, map[string]any{"type": "null"}}}
		}
		schema["additionalProperties"] = false
		schema["description"] = "OAuth overrides. Omit a field to preserve it; null resets it to automatic discovery."
		return schema
	}
	if t == reflect.TypeOf(time.Time{}) {
		return map[string]any{"type": "string", "format": "date-time"}
	}
	if t == reflect.TypeOf(config.Duration(0)) {
		return map[string]any{"type": "string", "description": "Duration, for example 30s or 2m."}
	}
	switch t.Kind() {
	case reflect.Bool:
		return map[string]any{"type": "boolean"}
	case reflect.String:
		return map[string]any{"type": "string"}
	case reflect.Int, reflect.Int32, reflect.Int64, reflect.Uint, reflect.Uint32, reflect.Uint64:
		return map[string]any{"type": "integer"}
	case reflect.Float32, reflect.Float64:
		return map[string]any{"type": "number"}
	case reflect.Slice:
		return map[string]any{"type": "array", "items": jsonSchemaForType(t.Elem())}
	case reflect.Map:
		return map[string]any{"type": "object", "additionalProperties": jsonSchemaForType(t.Elem())}
	case reflect.Struct:
		props := map[string]any{}
		for i := 0; i < t.NumField(); i++ {
			if name := jsonFieldName(t.Field(i)); name != "" {
				props[name] = jsonSchemaForType(t.Field(i).Type)
			}
		}
		return map[string]any{"type": "object", "properties": props}
	}
	return map[string]any{}
}

// profilesToolProperties builds every property of the tool's input schema: the
// ProfileConfig fields (reflected) plus operation and the operation arguments.
func profilesToolProperties() map[string]map[string]any {
	props := map[string]map[string]any{}
	t := reflect.TypeOf(config.ProfileConfig{})
	for i := 0; i < t.NumField(); i++ {
		name := jsonFieldName(t.Field(i))
		if name == "" {
			continue
		}
		schema := jsonSchemaForType(t.Field(i).Type)
		desc := profileConfigDescriptions[name]
		if desc == "" {
			desc = "create, update: profile field " + name + "."
		}
		schema["description"] = desc
		props[name] = schema
	}
	for _, a := range profilesOpArgs {
		schema := map[string]any{"type": a.typ, "description": a.desc}
		if a.enum != nil {
			schema["enum"] = a.enum
		}
		props[a.name] = schema
	}
	props["operation"] = map[string]any{
		"type": "string", "enum": profilesOperations,
		"description": "What to do. Every operation returns the data of its REST route.",
	}
	return props
}

// profilesToolOptions is the tool's option set: properties plus the required
// `operation`.
func profilesToolOptions() []mcp.ToolOption {
	props := profilesToolProperties()
	return []mcp.ToolOption{func(t *mcp.Tool) {
		if t.InputSchema.Properties == nil {
			t.InputSchema.Properties = map[string]any{}
		}
		for name, schema := range props {
			t.InputSchema.Properties[name] = schema
		}
		t.InputSchema.Required = append(t.InputSchema.Required, "operation")
	}}
}
